// Dark nav background wrapper — matches the real shell surface the trigger lives on.
function DarkShell({ children, style }) {
  return (
    <div style={{
      background: "var(--semantic-color-dark-mode-fill-static-surface-nav, #0a1223)",
      borderRadius: 8,
      padding: "8px 12px",
      display: "inline-flex",
      alignItems: "center",
      ...style,
    }}>
      {children}
    </div>
  );
}

export default {
  title: "Library/OrgSwitcher",
  component: OrgSwitcher,
  parameters: {
    docs: { description: { component: "**PLACEHOLDER** — awaiting spec review. Trigger only (panel not yet designed). See `org-switcher-spec.md`." } },
    layout: "padded",
    backgrounds: { default: "dark", values: [{ name: "dark", value: "#0a1223" }] },
  },
  argTypes: {
    orgName:    { control: "text",    name: "Org name",    description: "Full organisation name" },
    campusName: { control: "text",    name: "Campus name", description: "Full campus / sub-org name (empty if none)" },
    logoUrl:    { control: "text",    name: "Logo URL",    description: "Org logo image URL — omit to show initials placeholder" },
    open:       { control: "boolean", name: "Open",        description: "Flips the chevron (use when wiring up a panel)" },
    disabled:   { control: "boolean", name: "Disabled",    description: "True for single-org users — trigger renders but panel does not open" },
    mobile:     { control: "boolean", name: "Mobile",      description: "Force mobile abbreviated display regardless of viewport" },
  },
};

// ── Playground ────────────────────────────────────────────────────────────────
function PlaygroundTemplate({ logoUrl, ...args }) {
  const [open, setOpen] = useState(false);
  return (
    <DarkShell>
      <OrgSwitcher
        {...args}
        logoUrl={logoUrl || undefined}
        open={open}
        onClick={() => setOpen(o => !o)}
      />
    </DarkShell>
  );
}

export const Playground = PlaygroundTemplate.bind({});
Playground.args = {
  orgName: "Grace Community Church",
  campusName: "West",
  logoUrl: "",
  open: false,
  disabled: false,
  mobile: false,
};
Playground.storyName = "Playground";

